-- Baseline schema, recreated idempotently from scripts/001-006 so this migration
-- can run safely against both a brand-new database and an existing production one.
-- Do not edit this file once it has run anywhere real — add a new numbered migration instead.

CREATE TABLE IF NOT EXISTS users (
    id INT AUTO_INCREMENT PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    email VARCHAR(255) UNIQUE NOT NULL,
    on_camera BOOLEAN NOT NULL DEFAULT FALSE,
    discord_code VARCHAR(50) UNIQUE NOT NULL,
    registration_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    status ENUM('pending', 'confirmed', 'cancelled') DEFAULT 'pending',
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    INDEX idx_users_status (status),
    INDEX idx_users_on_camera (on_camera)
);

CREATE TABLE IF NOT EXISTS allowed_domains (
    id INT AUTO_INCREMENT PRIMARY KEY,
    domain VARCHAR(255) UNIQUE NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

INSERT IGNORE INTO allowed_domains (domain) VALUES
('@dcterra.nl'),
('@student.dcterra.nl');

CREATE TABLE IF NOT EXISTS admin_users (
    id INT AUTO_INCREMENT PRIMARY KEY,
    username VARCHAR(100) UNIQUE NOT NULL,
    password_hash VARCHAR(255) NOT NULL,
    email VARCHAR(255) UNIQUE NOT NULL,
    role ENUM('admin', 'super_admin') DEFAULT 'admin',
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    last_login TIMESTAMP NULL
);
-- Intentionally no seed row here: a known default password baked into version
-- control is a standing security hole. Bootstrap the first admin with
-- `pnpm db:create-admin` (scripts/create-admin.mjs) instead.

CREATE TABLE IF NOT EXISTS questions (
    id INT AUTO_INCREMENT PRIMARY KEY,
    question_text TEXT NOT NULL,
    question_type ENUM('text', 'textarea', 'select', 'radio', 'checkbox') NOT NULL,
    options JSON NULL,
    required BOOLEAN DEFAULT TRUE,
    category ENUM('on_camera', 'off_camera') NOT NULL,
    order_index INT DEFAULT 0,
    active BOOLEAN DEFAULT TRUE,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    INDEX idx_questions_category_active (category, active)
);

INSERT IGNORE INTO questions (question_text, question_type, category, order_index, required) VALUES
('What is your experience with being on camera?', 'select', 'on_camera', 1, true),
('Are you comfortable speaking in front of an audience?', 'radio', 'on_camera', 2, true),
