('registration_end_time', '2025-03-14 23:59:59', 'When registration closes'),
('event_title', '24H Livestream', 'Main event title'),
('event_description', 'Join us for a 24-hour livestream event', 'Event description'),
('registration_open', 'true', 'Whether registration is currently open');

CREATE TABLE IF NOT EXISTS team_signups (
  id INT AUTO_INCREMENT PRIMARY KEY,
  type ENUM('vrijwilliger', 'organisatie') NOT NULL,
  name VARCHAR(255) NOT NULL,
  organization_name VARCHAR(255),
  email VARCHAR(255) NOT NULL,
  phone VARCHAR(50),
  message TEXT,
  status ENUM('pending', 'approved', 'rejected') DEFAULT 'pending',
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  INDEX idx_team_signups_status (status),
  INDEX idx_team_signups_type (type)
);
